  ["_CeladonMansion3FWriterText"] = "¡Yo escribí la\nhistoria! ¿A que\ves guapa ERIKA?\f¡También me gusta\nmucho MISTY!\f¡Y también me\ngusta SABRINA!",
  ["_CeladonMansionRoofHouseHikerText"] = "¡Yo lo sé todo\nsobre el mundo de\vlos POKéMON de\vtu GAME BOY!\f¡Reúnete con tus\namigos y cambia\vPOKéMON!",
  ["_CeladonMansionRoofHouseSignText"] = "¡LO SÉ TODO!",
  ["_CeladonMart1FCurrentFloorSignText"] = "PB: PUESTO DE\nINFORMACIÓN",
  ["_CeladonMart1FDirectorySignText"] = "PB: PUESTO DE\nINFORMACIÓN\fP1: TIENDA DE\nENTRENADORES\fP2: VIDEOJUEGOS\fP3: REGALOS\fP4: FARMACIA\fÚLTIMO PISO:\nDISTRIBUIDORES",
  ["_CeladonMart1FReceptionistText"] = "¡Hola! Bienvenido\nal CENTRO\vCOMERCIAL de la\vCIUDAD AZULONA.\fEl tablero de la\nderecha es un\vplano de las\vtiendas.",
  ["_CeladonMart2FCurrentFloorSignText"] = "Objetos de máxima\ncalidad para los\ventrenadores.\fP1: TIENDA DE LOS\nENTRENADORES",
  ["_CeladonMart2FGirlText"] = "Para viajes\nlargos deberías\vcomprar REVIVIR.",
  ["_CeladonMart2FMiddleAgedManText"] = "El SÚPER REPEL\nmantiene a raya\va los POKéMON\vdébiles...\f¡Es un REPELENTE\nmás fuerte!",
  ["_CeladonMart3FClerkReceivedTM18Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!",
  ["_CeladonMart3FClerkTM18ExplanationText"] = "MT18 es CONTADOR.\n¡Venga vamos!...\v¡Buena suerte!",
  ["_CeladonMart3FClerkTM18NoRoomText"] = "¡Tu mochila está\nllena de cosas!",
  ["_CeladonMart3FClerkTM18PreReceiveText"] = "¡Hola! ¡Terminé!\n¡He completado\vPOKéMON!\f¿Tú no? Ten esto.\n¡Podría ayudarte!",
  ["_CeladonMart3FCurrentFloorSignText"] = "P2: VIDEOJUEGOS",
  ["_CeladonMart3FFightingGameText"] = "¡Un juego de\nlucha! ¡Parece\vmuy difícil!",
  ["_CeladonMart3FGameBoyKid1Text"] = "¡Todo POKéMON\ncapturado tiene\vun Nº IDENTIDAD y\vun EO, el nombre\vdel Entrenador\vOriginal que lo\vcapturó!",
  ["_CeladonMart3FGameBoyKid2Text"] = "¡Muy bien!\f¡Mi compañero va\na cambiarme su\vKANGASKHAN por\vmi GRAVELER!",
  ["_CeladonMart3FGameBoyKid3Text"] = "¡Un GRAVELER!\f¡Me gustan los\nGRAVELER! ¡Los\vcolecciono!\f¿Qué?\f¡GRAVELER se\ntransformó en\votro POKéMON!",
  ["_CeladonMart3FLittleBoyText"] = "¡Puedes\nidentificar a los\vPOKéMON que\vhayas cambiado\vpor su Nº ID!",
  ["_CeladonMart3FPokemonPosterText"] = "¡Rojo y Azul!\n¡Dos juegos de\vPOKéMON!",
  ["_CeladonMart3FPuzzleGameText"] = "¡Un juego de\npuzzles! ¡Parece\vmuy adictivo!",
  ["_CeladonMart3FRPGText"] = "Un juego de rol.\n¡Genial! ¡Pero\vno tengo tiempo!",
  ["_CeladonMart3FSNESText"] = "¡Es una SUPER\nNINTENDO!",
  ["_CeladonMart3FSportsGameText"] = "¡Un juego de\ndeportes! ¡A mi\vpadre le gustan!",
  ["_CeladonMart4FCurrentFloorSignText"] = "¡Dilo con un\nregalo!\fP3: REGALOS\f¡Evolución\nEspecial!\v¡Diversas PIEDRAS\vElementales en\vventa!",
  ["_CeladonMart4FSuperNerdText"] = "¡Compraré una\nPOKé MUÑECA\vpara mi novia!",
  ["_CeladonMart4FYoungsterText"] = "¡Me dijeron una\ncosa!\f¡Puedes huir de\nun POKéMON\vsalvaje si le\vdistraes con una\vPOKé MUÑECA!",
  ["_CeladonMart5FCurrentFloorSignText"] = "P4: FARMACIA",
  ["_CeladonMart5FGentlemanText"] = "¡Los dispositivos\nde mejora de los\vPOKéMON sólo\vse venden aquí!\fUsa CALCIO para\naumentar las\vhabilidades\vESPECIALES.\fUsa CARBURANTE\npara aumentar la\vVELOCIDAD.",
  ["_CeladonMart5FSailorText"] = "¡He venido a por\ndispositivos de\vmejora de los\vPOKéMON!\fLas PROTEÍNAS\naumentan la\vpotencia del\vATAQUE.\fEl HIERRO aumenta\nla DEFENSA.",
  ["_CeladonMartRoofCurrentFloorSignText"] = "ÚLTIMO PISO:\nDISTRIBUIDORES",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "¡Tengo sed!\n¡Me gustaría\vbeber algo!\f¿Le das algo\nde beber?",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "¿Qué bebida\nquieres darle?",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "¡No, gracias!\n¡No estoy tan\vsedienta!",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "¡Tengo sed!\n¡Me gustaría\vbeber algo!",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "¡No tienes sitio\npara esto!",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "¡{PLAYER} recibió\nMT49!",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "¡{RAM:wStringBuffer}\ncontiene el\vRAYO HIELO!\f¡Éste puede helar\nal enemigo, a\vveces!",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "¡{RAM:wStringBuffer} incluye\nla AVALANCHA!\fEste ataque puede\natizar al enemigo\valgunas veces...",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "¡La MT49 contiene\nel TRI-ATAQUE!",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "¡Yay!\f¡AGUA!\f¡Gracias!\f¡Tómala,\ntoda tuya!",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "¡Genial!\f¡LIMONADA!\f¡Gracias!\f¡Tómala,\ntoda tuya!",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "¡Genial!\f¡Un REFRESCO!\f¡Gracias!\f¡Tómala,\ntoda tuya!",
  ["_CeladonMartRoofSuperNerdText"] = "Mi hermana es\nentrenadora,\v¡de verdad!\f¡Pero es tan\ninfantil que\vme vuelve loco!",
  ["_CeladonPokecenterBeautyText"] = "¡Pedaleé cuesta\narriba por el\vCAMINO de BICIS\vdesde FUCSIA!",
  ["_CeladonPokecenterGentlemanText"] = "¡La POKé FLAUTA\ndespierta a los\vPOKéMON con un\vsonido que sólo\vellos pueden oír!",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "El ATAQUE de todo\nPOKéMON\vaumenta un poco.\fY podrás usar el\nDESTELLO siempre\vque quieras.",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "Los POKéMON de\nnivel inferior a 30 te obedecerán.\f¡Los de nivel\nsuperior, serán\vincontrolables!\fY podrás usar\nCORTAR fuera del\vcombate.",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "¡Todos los\nPOKéMON\vte obedecerán!",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "Los POKéMON de\nnivel inferior a 70 te obedecerán.\f¡Los de nivel\nsuperior serán\vincontrolables!",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "Sólo tienen\nMEDALLAS los\ventrenadores\vmás hábiles.\fYa veo que tienes\nuna por lo menos.\f¡Esas MEDALLAS\nguardan secretos\vincreíbles!",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Ven a verme\ncuando quieras.",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Dime...\f¿Cuál de las 8\nMEDALLAS debería\vdescribirte?",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "Los POKéMON de\nnivel inferior a 50 te obedecerán.\f¡Los de nivel\nsuperior serán\vincontrolables!\fY podrás usar la\nFUERZA fuera del\vcombate.",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "La DEFENSA de\ntodos los POKéMON\vaumenta un poco.\fY podrás usar el\nSURF fuera del\vcombate.",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "La VELOCIDAD de\ntodos los POKéMON\vaumenta un poco.\fY podrás utilizar\nVOLAR fuera del\vcombate.",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "Las habilidades\nESPECIALES de\vtus POKéMON\vaumentan un poco.",
  ["_CeruleanCityBikeShopSign"] = "¡Hierbas y cuevas\nbajo control!\vTIENDA-BICIS",
  ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "¡SLOWBRO dale un\npuñetazo! ¡No!\v¡Volviste a\vfallar!",
  ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "¡BIEN! ¡SLOWBRO!\n¡Usa la BOMBA\vSÓNICA! ¡Venga,\vSLOWBRO, presta\vatención!",
  ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "¡SLOWBRO, APARTA!\n¡No! ¡Qué mal!\f¡Es tan difícil\ncontrolar a los\vPOKéMON!\f¡La obediencia de\ntus POKéMON\vdepende de tus\vhabilidades como\ventrenador!",
  ["_CeruleanCityCooltrainerF2Text"] = "Quiero una bonita\nBICICLETA roja.\f¡La guardaré en\ncasa para que no\vse ensucie!",
  ["_CeruleanCityCooltrainerMText"] = "¿También eres\nentrenador?\vRecoger, luchar,\v¡qué vida tan\vdura la nuestra!",
  ["_CeruleanCityGuardText"] = "A esta gente le\nhan robado.\f¡Seguro que el\nTEAM ROCKET tiene\valguna relación\vcon este \vatroz crimen!\f¡Hasta nuestra\nPOLICÍA tiene\vproblemas con\vlos ROCKET!",
  ["_CeruleanCityGymSign"] = "LÍDER del GIMNASIO\nPOKéMON de la\vCIUDAD CELESTE:\vMISTY\f¡La sirena\ndistorsionada!",
  ["_CeruleanCityRivalDefeatedText"] = "¡Oye!\n¡Tranquilo!\v¡Ya has ganado!",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: ¿Sabes\nqué me pasó?\f¡Estuve con BILL\ny conseguí que me\venseñara sus\vraros POKéMON!\f¡Y eso añadió\nmuchas páginas\va mi POKéDEX!\f¡Por algo BILL es\nmundialmente\vconocido como\vPOKéMANÍACO!\f¡Él inventó el\nSistema de\vAlmacenamiento\vde POKéMON\vpara PC!\f¡Como estás\nusando su sistema\vdale las gracias!\f¡En fin, mejor\nque me vaya!\v¡Hasta luego!",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: ¡Hola\n{PLAYER}!\f¿Sigues avanzando\npenosamente?\f¡Por aquí todo va\ngenial! ¡Atrapé\vun montón de\vinteligentes y\vfuertes POKéMON!\f¡Vale {PLAYER},\nveamos qué has\vatrapado!",
  ["_CeruleanCityRivalVictoryText"] = "¡Je!\n¡Soy demasiado\vgenial para ti!",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "¡Mejor que me\nvaya! ¡Adiós!",
  ["_CeruleanCityRocketIGiveUpText"] = "¡Alto!\n¡Me rindo!\v¡Me iré\vtranquilamente!",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "¡Vale! ¡Devolveré\nla MT que robé!",
  ["_CeruleanCityRocketReceivedTM28Text"] = "¡{PLAYER} recuperó\nla MT28!",
  ["_CeruleanCityRocketTM28NoRoomText"] = "¡Hazle sitio\na esto!\f¡No puedo irme\nhasta dártelo!",
  ["_CeruleanCityRocketText"] = "¡Oye! ¡Fuera de\naquí! ¡Esto no\vte pertenece!\v¿Quién? ¿Yo?\f¡Soy un inocente\npeatón! ¿Es que\vno me crees?",
  ["_CeruleanCitySignText"] = "¡CIUDAD CELESTE!\n¡Una misteriosa\vaura azulada la\vrodea!",
  ["_CeruleanCitySlowbroIgnoredOrdersText"] = "SLOWBRO ignoró\nlas órdenes...",
  ["_CeruleanCitySlowbroIsLoafingAroundText"] = "SLOWBRO está\nholgazaneando...",
  ["_CeruleanCitySlowbroTookASnoozeText"] = "SLOWBRO se\ndurmió...",
  ["_CeruleanCitySlowbroTurnedAwayText"] = "SLOWBRO se\nalejó...",
  ["_CeruleanCitySuperNerd1Text"] = "Ese arbusto que\nhay delante de\vla tienda me\vimpide pasar.\fDebería poder\nesquivarlo.",
  ["_CeruleanCitySuperNerd2Text"] = "¿Estás haciendo\nuna enciclopedia\vde los POKéMON?\v¡Qué increíble!",
  ["_CeruleanCitySuperNerd3Text"] = "¡Ésta es la CUEVA\nCELESTE! ¡En ella\vviven unos\vPOKéMON\vsúper fuertes!\f¡Sólo puede\nentrar el campeón\vde la LIGA\vPOKéMON!",
  ["_CeruleanCityTrainerTipsText"] = "PISTAS ENTRENADOR\fPulsar el botón B\ndurante la\vevolución\vcancelará todo\vel proceso.",
  ["_CeruleanGymAfterBattleText1"] = "Tienes que luchar\ncontra otros\ventrenadores para\vsaber lo bueno\vque eres.",
  ["_CeruleanGymAfterBattleText2"] = "¡MISTY seguirá\nmejorando!\f¡Y no perderá con\nalguien como tú!",
  ["_CeruleanGymBattleText1"] = "¡Soy demasiado\nbuena para ti!\f¡MISTY puede\nesperar!",
  ["_CeruleanGymBattleText2"] = "¡Splash!\f¡Soy el primero!\n¡Al ataque!",
  ["_CeruleanGymEndBattleText1"] = "\n¡Me machacaste!",
  ["_CeruleanGymEndBattleText2"] = "¡No\npuede ser!",
  ["_CeruleanGymGymGuideBeatMistyText"] = "¡Ganaste a MISTY!\n¿Qué decirte?\f¡Tú y yo formamos\nun equipo súper\vfuerte!",
  ["_CeruleanGymGymGuideChampInMakingText"] = "¡Hola,\nposible campeón!\f¡Un consejo!\f¡La LÍDER, MISTY,\nes profesional y\vusa POKéMON\vacuáticos!\f¡Puedes absorber\ntoda su agua con\vlos POKéMON\vdel tipo-planta!\f¡O atrápalos con\nla electricidad!",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "¡La MEDALLA\nCASCADA obligará\va todos los\vPOKéMON por\vdebajo del nivel 30 a obedecer!\f¡Incluidos los\nforasteros!\f¡Y podrás usar\nCORTAR siempre\vque quieras!\f¡Puedes CORTAR\npequeños arbustos\vpara abrir\vnuevos caminos!\f¡Y te daré mi\nMT favorita!",
  ["_CeruleanGymMistyPreBattleText"] = "¡Hola! ¡Tú eres\nnuevo por aquí!\f¡Los entrenadores\nprofesionales\vdeben tener una\vestrategia para\vsus POKéMON!\f¿Qué táctica\nsigues tú para\vatrapar a los\vPOKéMON?\f¡Mi táctica es la\nofensiva total\vcon los POKéMON\vdel tipo-agua!",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "¡Uauuu!\n¡Eres demasiado!\f¡Muy bien!\f¡Toma la MEDALLA\nCASCADA para que\vtodos sepan que\vme ganaste!",
  ["_CeruleanGymMistyReceivedTM11Text"] = "¡{PLAYER} obtiene\nla MT11!",
  ["_CeruleanGymMistyTM11ExplanationText"] = "¡La MT11 enseña\nel RAYO BURBUJA!\f¡Úsala con los\nPOKéMON de agua!",
  ["_CeruleanGymMistyTM11NoRoomText"] = "¡Mejor que le\nhagas sitio!",
  ["_CeruleanMartCooltrainerFText"] = "¿Has visto algún\nCARAMELO RARO?\f¡Dicen que un\nPOKéMON subirá\vun nivel\vsi se lo come!",
  ["_CeruleanMartCooltrainerMText"] = "Usa el REPELENTE\npara evitar a los\vbichos y a los\vPOKéMON débiles.\f¡Pon a tu POKéMON\nmás fuerte el\vprimero de la\vlista para\vconseguir mejores\vresultados!",
  ["_CeruleanPokecenterGentlemanText"] = "¿Has oído hablar\nde BILL?\f¡Dicen que es un\nPOKéMANÍACO!\fPero yo creo que\nla gente le tiene\vmucha envidia.\f¿Quién no querría\npresumir de sus\vPOKéMON?",
  ["_CeruleanPokecenterGuyText"] = "¡BILL tiene\nmuchísimos\vPOKéMON!\f¡Y algunos son\nmuy raros!",
  ["_CeruleanPokecenterSuperNerdText"] = "¡Ese BILL!\f¡Dicen que haría\nlo que fuera para\vconseguir raros\vPOKéMON!",
  ["_CeruleanTradeHouseGrannyText"] = "A mi marido le\ngusta cambiar\vPOKéMON.\fSi eres un\ncoleccionista,\v¿podrías cambiar\vcon él?",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "¡Esos malditos\nROCKET!\f¡Mira lo que\nhicieron aquí!\f¡Robaron una MT\npara enseñar a\vlos POKéMON cómo\vEXCAVAR hoyos!\f¡Y eso me trajo\nmuchos problemas!",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "¡Lo perdido\nperdido está!\f¡Y decidí enseñar\na DIGLETT cómo\vEXCAVAR sin\vtener una MT!",
  ["_CeruleanTrashedHouseGirlText"] = "¡El TEAM ROCKET\nestará intentando\vEXCAVAR su camino\vde maldades!",
  ["_CeruleanTrashedHouseWallHoleText"] = "¡El TEAM ROCKET\nabrió una nueva\vsalida!",
  ["_ChampionsRoomOakComeWithMeText"] = "OAK: ¡{PLAYER}!\f¡Sabes que tu\nvictoria no fue\vdebida sólo a\vti!\f¡El vínculo que\nmantienes con tus\vPOKéMON es\vmaravilloso!\f¡{PLAYER}!\n¡Ven conmigo!",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "OAK: ¡Ganaste!\n¡Enhorabuena!\v¡Eres el nuevo\vcampeón de la\vLIGA POKéMON!\f¡Has crecido\ntanto desde que\vte fuiste con\v{RAM:wNameBuffer}!\f¡{PLAYER}, ya\neres mayor!",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "OAK: ¡{RIVAL}!\n¡Estoy desolado!\f¡Vine en cuanto\nsupe que habías\vderrotado al ALTO\vMANDO!\f¡Pero cuando\nllegué aquí,\vya habías sido\vderrotado!\f¡{RIVAL}!\n¿Entiendes por\vqué has perdido?\f¡Olvidaste tratar\na tus POKéMON\vcon cariño y\vconfianza!\f¡Y sin ellos,\njamás volverás a\vser un campeón!",
  ["_ChampionsRoomOakText"] = "OAK: ¡{PLAYER}!",
  ["_ChampionsRoomRivalAfterBattleText"] = "¿Qué? ¿Cómo\nhe podido perder?\fHe entrenado a\nmis POKéMON a\vla perfección.\f¡Maldición! ¡Eres\nel nuevo campeón\vde la LIGA\vPOKéMON!\fAunque no me\nguste admitirlo.",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}: ¡Hola!\f¡Estaba deseando\nverte {PLAYER}!\f¡Mi rival debería\nser fuerte para\vpoder mantenerme\ven forma!\f¡Utilizando mi\nPOKéDEX, he\vbuscado los\vPOKéMON más\vfuertes!\f¡Y he creado\nvarios equipos\vque derrotarían\va cualquier tipo\vde POKéMON!\f¡Y ahora!\f¡Yo soy el\ncampeón de la\vLIGA POKéMON!\f¡{PLAYER}!\n¿Sabes lo que\vsignifica eso?\f¡Te lo diré!\f¡Yo soy el mejor\nentrenador\vdel mundo!",
  ["_ChanseyDexEntry"] = "Un raro y evasivo\nPOKéMON que,\vsegún dicen, trae\fla felicidad a\naquellos que lo\vatrapan",
  ["_ChargeMoveEffectText"] = "¡{USER}",
  ["_CharizardDexEntry"] = "Escupe fuego tan\ncaliente que\vfunde las rocas.\fCausa incendios\nforestales\vsin querer",
  ["_CharmanderDexEntry"] = "Prefiere los\nsitios calientes.\vDicen que cuando\fllueve sale vapor\nde la punta\vde su cola",
  ["_CharmeleonDexEntry"] = "Cuando balancea\nsu ardiente cola,\veleva la\ftemperatura a\nniveles muy\valtos",
  ["_ChooseABoxText"] = "Elige una CAJA\nde POKéMON.",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "¡El FUEGO es lo\nmáximo en la\vtécnica de las\vquemaduras!\f¡No lo malgastes\ncon los POKéMON\vacuáticos!",
  ["_CinnabarGymBlainePreBattleText"] = "¡Ja!\f¡Soy BLAINE!\n¡LÍDER del\vGIMNASIO de la\vCIUDAD CANELA!\f¡Mis feroces\nPOKéMON\vquemarán a\vtodo aquel que\vme desafíe!\f¡Ja! ¡Mejor que\ntengas el\vANTIQUEMADURAS!",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "¡Me has\nmachacado!\f¡Has ganado la\nMEDALLA-VOLCÁN!",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "¡La MT38 incluye\nla LLAMARADA!\f¡Enseña este\nataque a los\vPOKéMON del\vtipo-fuego!\f¡CHARMELEON o\nPONYTA serían las\vmejores apuestas!",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "¡Hazle sitio a\nmi regalo!",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "¡Ja!\f¡La MEDALLA-\nVOLCÁN mejora\vlas habilidades\vESPECIALES de\vtus POKéMON!\f¡Mira, también\nte daré esto!",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "¡{PLAYER}, ganaste\na esa antorcha\vde fuego!",
  ["_CinnabarGymGymGuideChampInMakingText"] = "¡Hola, posible\ncampeón!\f¡BLAINE es un\nprofesional de\vlos POKéMON\vdel fuego!\f¡Apaga con agua\nsus ánimos!\f¡Mejor que lleves\nANTIQUEMADURAS!",
  ["_CinnabarGymQuizCorrectText"] = "¡Respuesta\ncorrecta!\f¡Adelante!",
  ["_CinnabarGymQuizIncorrectText"] = "¡Mal! ¡Lo siento!",
  ["_CinnabarGymQuizIntroText"] = "¡POKéAcertijo!\f¡Responde bien y\nabrirás la puerta\va la siguiente\vhabitación!\f¡Responde mal y\nlucharás contra\vun entrenador!\fSi prefieres\nguardar tus\vPOKéMON para\vel LÍDER del\vGIMNASIO...\f¡Hazlo bien!\n¡Vamos allá!",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "Fuego, o para ser\nmás preciso,\vcombustión...\f¡Bla, bla, bla,\nbla!...",
  ["_CinnabarGymSuperNerd1BattleText"] = "¿Sabes el calor\nque puede dar el\valiento de fuego\vde un POKéMON?",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "¡Ay!\n¡Quema, quema!",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "¡No puedo evitar\nrobar los \vPOKéMON de\votras personas!",
