  ["_OKExclamationText"] = "¡VALE!",
  ["_OakLabEmailText"] = "¡Aquí hay un\nmensaje e-mail!\f...\f¡Aviso a todos\nlos entrenadores\vde POKéMON!\f¡Los entrenadores\nde élite de la\vLIGA POKéMON\vestán listos\vpara desafiaros\va todos!\f¡Traed a vuestros\nmejores POKéMON\vy descubrid\vvuestra \vpuntuación como\ventrenadores!\fCG de la LIGA\nPOKéMON\vMESETA AÑIL\fPD: ¡PROF. OAK,\nvisítenos por\vfavor!...",
  ["_OakSpeechText1"] = "¡Hola a todos!\n¡Bienvenidos al\vmundo de POKéMON!\f¡Me llamo OAK!\n¡Pero la gente me\vllama el PROFESOR\vPOKéMON!",
  ["_OakSpeechText2A"] = "¡Este mundo está\nhabitado por unas\vcriaturas\vllamadas POKéMON!",
  ["_OakSpeechText2B"] = "Para algunos, los\nPOKéMON son\vmascotas. Pero\votros los usan\vpara pelear.\fEn cuanto a mí...\fEstudio a los\nPOKéMON como\vprofesión.",
  ["_OakSpeechText3"] = "¡{PLAYER}!\f¡Tu propia\nleyenda POKéMON\vestá a punto de\vcomenzar!\f¡Te espera un\nmundo de sueños\vy aventuras con\vlos POKéMON!\v¡Adelante!",
  ["_OaksAideComeBackText"] = "¡Ah! Ya veo.\fCuando tengas {NUM:hOaksAideRequirement, 1, 3}\ntipos, vuelve a\vpor {RAM:wOaksAideRewardItemName}.",
  ["_OaksAideGotItemText"] = "¡{PLAYER} obtuvo\n{RAM:wOaksAideRewardItemName}!",
  ["_OaksAideHereYouGoText"] = "¡Bien! ¡Has\nlogrado {NUM:hOaksAideNumMonsOwned, 1, 3} tipos \vde POKéMON!\v¡Enhorabuena!\f¡Aquí tienes!",
  ["_OaksAideHiText"] = "¡Hola! ¿Te\nacuerdas de mí?\v¡Soy AYUDANTE\vdel PROF. OAK!\f¡Si atrapaste {NUM:hOaksAideRequirement, 1, 3}\ntipos de POKéMON,\vse supone que\vdebería darte\v{RAM:wOaksAideRewardItemName}!\f¡Bien {PLAYER}!\n¿Atrapaste por lo\vmenos {NUM:hOaksAideRequirement, 1, 3} tipos\vde POKéMON?",
  ["_OaksAideNoRoomText"] = "¡Oh! Ya veo que\nno tienes\vsitio para\v{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Veamos...\n¡Oh! ¡Atrapaste\vsolamente {NUM:hOaksAideNumMonsOwned, 1, 3}\vtipos de POKéMON!\fNecesitas {NUM:hOaksAideRequirement, 1, 3}\ntipos si quieres\v{RAM:wOaksAideRewardItemName}.",
  ["_OaksLabGirlText"] = "¡El PROF. OAK es\nun experto en\vPOKéMON!\f¡Es admirado por\nmuchos de los\ventrenadores de\vPOKéMON!",
  ["_OaksLabGivePokeballsExplanationText"] = "Cuando aparezca\nun POKéMON\vsalvaje, lucha\vcontra él.\f¡Lánzale una\nPOKé BALL para\vcapturarlo!\f¡Pero esto no\nsiempre funciona!\f¡Un POKéMON\nsano podría huir!\v¡También cuenta\vla suerte!",
  ["_OaksLabLastMonText"] = "¡Ése es el último\nPOKéMON del\vPROF. OAK!",
  ["_OaksLabMonEnergeticText"] = "¡Este POKéMON es\nmuy energético!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "OAK: Ven a verme\nde vez en cuando.\f¡Tenme informado\nsobre cómo te va\vcon tu POKéDEX!",
  ["_OaksLabOak1DeliverParcelText"] = "OAK: ¡{PLAYER}!\f¿Cómo va tu\nPOKéMON?\f¡Creo que te\nquiere mucho!\f¡Pareces ser\nmuy hábil como\ventrenador de\vPOKéMON!\f¿Qué? ¿Tienes\nalgo para mí?\f{PLAYER} entregó\nel CORREO de OAK.",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "OAK : ¡Encantado\nde verte! ¿Cómo\vva tu POKéDEX?\v¡Déjame que le\veche un vistazo!",
  ["_OaksLabOak1ParcelThanksText"] = "¡Ah, sí! ¡Es la\nPOKé BALL que\vhabía encargado!\v¡Gracias!",
