  ["_OaksLabOak1WhichPokemonDoYouWantText"] = "OAK: {PLAYER},\n¿Qué POKéMON\vquieres?",
  ["_OaksLabOak1YourPokemonCanFightText"] = "OAK: ¡Si aparece\nun POKéMON\vsalvaje, tu\vPOKéMON podrá\vluchar contra él!",
