  ["_PewterCitySuperNerd2ThatsRightText"] = "¡Eso es! ¡Es un\nduro trabajo!",
  ["_PewterCityTrainerTipsText"] = "PISTAS ENTRENADOR\f¡Todo POKéMON\nque luche en una\vbatalla ganará\vEXPERIENCIA!",
