  ["_PewterGymCooltrainerMEndBattleText"] = "¡Mm!\f¡Años luz no son\ntiempo! ¡Miden\vdistancia!",
  ["_PewterGymGuideAdviceText"] = "¡El 1er POKéMON\nque sale a luchar\ves el primero de\vla LISTA de\vPOKéMON!\f¡Cambiar el orden\nde los POKéMON\vpodría facilitar\vlos combates!",
