  ["_RivalDefeatedText"] = "¡NO!\n¡Eso es\vimposible! ¡Me\vhas derrotado!\f¡Tras tantos\nesfuerzos por\vconvertirme en\vcampeón de LIGA!\f¿Se ha terminado\nya mi reinado?\v¡No es justo!",
  ["_RivalVictoryText"] = "¡Jajaja!\n¡Gané, gané!\f¡{PLAYER}, soy\ndemasiado bueno\vpara ti!\f¡Lograste llegar\na mi, {RIVAL},\vel genio de\vlos POKéMON!\f¡Bien hecho,\nperdedor!\v¡Ja ja ja!",
  ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "¡Vi a un MACHOP\nen este túnel!",
  ["_RockTunnel1FCooltrainerF1BattleText"] = "¡Oye! ¡No hagas\ntonterías en la\voscuridad!",
  ["_RockTunnel1FCooltrainerF1EndBattleText"] = "\n¡Estaba\vdemasiado oscuro!",
  ["_RockTunnel1FCooltrainerF2AfterBattleText"] = "¡Parecías muy\nmono e indefenso!",
  ["_RockTunnel1FCooltrainerF2BattleText"] = "¡Vine hasta aquí\npor los POKéMON!",
  ["_RockTunnel1FCooltrainerF2EndBattleText"] = "\n¡Me he quedado\vsin POKéMON!",
  ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "¡Ufff! ¡Estoy\nsudando ahora!",
  ["_RockTunnel1FCooltrainerF3BattleText"] = "¡Tienes POKéMON!\n¡Empecemos!",
  ["_RockTunnel1FCooltrainerF3EndBattleText"] = "\n¡Juegas duro!",
  ["_RockTunnel1FHiker1AfterBattleText"] = "Cuidado con ONIX.\n¡Podría apretarte\vlas clavijas!",
  ["_RockTunnel1FHiker1BattleText"] = "¡Este oscuro túnel\nrecorre un largo\vcamino, chico!",
  ["_RockTunnel1FHiker1EndBattleText"] = "¡Uauu!\n¡Tú ganas!",
  ["_RockTunnel1FHiker2AfterBattleText"] = "Ese POKéMON\ndormido de la\vRUTA 12 me obligó\va desviarme.",
  ["_RockTunnel1FHiker2BattleText"] = "Mmm. Puede que me\nhaya perdido...",
  ["_RockTunnel1FHiker2EndBattleText"] = "\n¡Tranquilo!\v¿Qué hago?\v¿Por dónde salgo?",
  ["_RockTunnel1FHiker3AfterBattleText"] = "¡Tienes madera de\nbuen montañero!",
  ["_RockTunnel1FHiker3BattleText"] = "¡Los forasteros\ncomo tú deberían\vrespetarme!",
  ["_RockTunnel1FHiker3EndBattleText"] = "\n¡Me rindo!",
  ["_RockTunnel1FSignText"] = "TÚNEL ROCA:\nCIUDAD CELESTE -\vPUEBLO LAVANDA",
  ["_RockTunnel1FSuperNerdAfterBattleText"] = "¡Conseguiré un\nZUBAT por\vel camino!",
  ["_RockTunnel1FSuperNerdBattleText"] = "¡Lucha POKéMON!\n¿Listo? ¡YA!",
  ["_RockTunnel1FSuperNerdEndBattleText"] = "\n¡Final del\vjuego!",
  ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "¡Quiero volver\na mi casa!",
  ["_RockTunnelB1FCooltrainerF1BattleText"] = "Los montañeros\nmarcan el camino\vcon ramitas.",
  ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "\n¡Ohhh! ¡Yo hice\vtodo lo posible!",
  ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "¡Me gustan los\nPOKéMON pequeños!\v¡Los grandes son\vhorribles!",
  ["_RockTunnelB1FCooltrainerF2BattleText"] = "¡No suelo venir\npor aquí, pero\vlucharé contigo!",
  ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "\n¡Oh! ¡He perdido!",
  ["_RockTunnelB1FHiker1AfterBattleText"] = "¡Prefiero la\nfuerza porque no\vme gusta pensar!",
  ["_RockTunnelB1FHiker1BattleText"] = "¡Jajaja! ¿Crees\npoder ganarme?",
  ["_RockTunnelB1FHiker1EndBattleText"] = "¡Uups!\nNivel muscular:\v¡Cero!",
  ["_RockTunnelB1FHiker2AfterBattleText"] = "En las montañas\nsuele haber\vPOKéMON del\vtipo-roca.",
  ["_RockTunnelB1FHiker2BattleText"] = "¡Mis técnicas de\nPOKéMON te\vharán llorar!",
  ["_RockTunnelB1FHiker2EndBattleText"] = "\n¡Me rindo!\v¡Tus técnicas\vson mejores!",
  ["_RockTunnelB1FHiker3AfterBattleText"] = "¡Criaré a mis\nPOKéMON para\vque destruyan a\vlos tuyos!",
  ["_RockTunnelB1FHiker3BattleText"] = "¡Lánzame tu\nmejor ataque!",
  ["_RockTunnelB1FHiker3EndBattleText"] = "\n¡Vamos, adelante!",
  ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "Cuando termines\ncon tu POKéDEX\v¿me la dejarás?",
  ["_RockTunnelB1FSuperNerd1BattleText"] = "¿Tienes una\nPOKéDEX? ¡Yo\vtambién quiero\vuna!",
  ["_RockTunnelB1FSuperNerd1EndBattleText"] = "\n¡Brgg! ¡Me das\vtanta envidia!",
  ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "Los jugadores\ndisfrazados\vvisten como los\vPOKéMON para\vdivertirse.",
  ["_RockTunnelB1FSuperNerd2BattleText"] = "¿Qué sabes de\nesos jugadores\vdisfrazados?",
  ["_RockTunnelB1FSuperNerd2EndBattleText"] = "Pues\neso es todo.",
  ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "Soy un artista,\nno un guerrero.",
  ["_RockTunnelB1FSuperNerd3BattleText"] = "Cuando estoy en\ncasa, dibujo a\vlos POKéMON.",
  ["_RockTunnelB1FSuperNerd3EndBattleText"] = "¡Uf!\n¡Estoy agotado!",
  ["_RockTunnelPokecenterFisherText"] = "¡Vendí una inútil\nPEPITA por 5000$!",
  ["_RockTunnelPokecenterGentlemanText"] = "¡Los POKéMON\nde ciertos\velementos son más\vo menos fuertes\vque otros!",
  ["_RockTunnelPokecenterGuyText"] = "¡Dicen que hay\nGHOST en el\vPUEBLO LAVANDA!",
  ["_RocketHide3AfterBattleText3"] = "¡Venga, adelante!\n¡Pero necesitarás\vla LLAVE DEL\vASCENSOR!",
  ["_RocketHideout3BattleText"] = "¡Nos dijeron\ndesde arriba\vque venías!",
  ["_RocketHideout3EndBattleText3"] = "¿Qué?\n¿He perdido? ¡NO!",
  ["_RocketHideoutB1FRocket1AfterBattleText"] = "¿Vas a luchar\ncontra el\vTEAM ROCKET?",
  ["_RocketHideoutB1FRocket1BattleText"] = "¿Quién eres tú?\n¿Y cómo has\vllegado aquí?",
  ["_RocketHideoutB1FRocket1EndBattleText"] = "¡Auuu!\n¡He perdido!",
  ["_RocketHideoutB1FRocket2AfterBattleText"] = "¡No te vas a\nsalir con la\vtuya, mocoso!",
  ["_RocketHideoutB1FRocket2BattleText"] = "¡Has destrozado\nnuestros planes!",
  ["_RocketHideoutB1FRocket2EndBattleText"] = "\n¡Chamuscado!",
  ["_RocketHideoutB1FRocket3AfterBattleText"] = "¿El SCOPE SILPH?\n¡No sé dónde\vestá!",
  ["_RocketHideoutB1FRocket3BattleText"] = "¡Alerta!\n¡Hay un intruso!",
  ["_RocketHideoutB1FRocket3EndBattleText"] = "¡¡¡No\npude hacerlo!!!",
  ["_RocketHideoutB1FRocket4AfterBattleText"] = "¡VALE, hablaré!\n¡Toma el ascensor\vpara ver a\vmi JEFE!",
  ["_RocketHideoutB1FRocket4BattleText"] = "¿Por qué has\nvenido aquí?",
  ["_RocketHideoutB1FRocket4EndBattleText"] = "¡Esto\nno funcionará!",
  ["_RocketHideoutB1FRocket5AfterBattleText"] = "¡Oh-oh, esa pelea\nabrió la puerta!",
  ["_RocketHideoutB1FRocket5BattleText"] = "¿Te has perdido,\npequeñajo?",
  ["_RocketHideoutB1FRocket5EndBattleText"] = "\n¿Por qué...?",
  ["_RocketHideoutB2FRocketAfterBattleText"] = "El CG del TEAM\nROCKET tiene 4\vsótanos. ¿Podrás\vllegar al JEFE?",
  ["_RocketHideoutB2FRocketBattleText"] = "¡El JEFE dijo que\nse pueden ver\vfantasmas con\vel SCOPE SILPH!",
  ["_RocketHideoutB2FRocketEndBattleText"] = "\n¡Me rindo!",
  ["_RocketHideoutB3FRocket1AfterBattleText"] = "¿El SCOPE SILPH?\nLa máquina que\vrobó el JEFE.\vDebe de estar\vpor aquí.",
  ["_RocketHideoutB3FRocket1BattleText"] = "¡Deja de meterte\nen los asuntos\vdel TEAM ROCKET!",
  ["_RocketHideoutB3FRocket1EndBattleText"] = "¡Uff!\n¡Me tumbaron!",
  ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "Ya veo que has\nentrenado a tus\vPOKéMON con\vmucho cuidado.\f¡Un niño como tú\njamás entendería\vcuáles son mis\vplanes!\f¡En esta ocasión\nte dejaré pasar!\fEspero que nos\nvolvamos a ver.",
  ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "¡Mmm! ¡Estoy muy\nimpresionado de\vque hayas llegado\vhasta aquí!",
  ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "¿QUÉ?\n¡Esto es\vimposible!",
  ["_RocketHideoutB4FRocket1AfterBattleText"] = "¿Tienes algo\nen contra del\vTEAM ROCKET?",
  ["_RocketHideoutB4FRocket1BattleText"] = "¡Te conozco! ¡Tú\narruinaste\vnuestros planes\ven MT. MOON!",
  ["_RocketHideoutB4FRocket1EndBattleText"] = "\n¡Chamuscado\votra vez!",
  ["_RocketHideoutB4FRocket2AfterBattleText"] = "¡JEFE! ¡Siento\nhaberle fallado!",
  ["_RocketHideoutB4FRocket2BattleText"] = "¿Acaso no ves\nla belleza de\vnuestros actos\vmalvados?",
  ["_RocketHideoutB4FRocket2EndBattleText"] = "¡Ayayay!",
  ["_RocketHideoutB4FRocket3AfterBattleText"] = "¡Oh no! ¡He\nperdido la LLAVE\vdel ASCENSOR!",
  ["_RocketHideoutB4FRocket3BattleText"] = "¿No funciona el\nascensor? ¿Quién\vtiene la LLAVE\vdel ASCENSOR?",
  ["_RocketHideoutB4FRocket3EndBattleText"] = "¡No!",
  ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "¡Parece necesitar\nuna llave!",
  ["_RoseText"] = "creció!",
  ["_Route10CooltrainerF1AfterBattleText"] = "Vi a algunos\nPOKéMANÍACOS\vpor ahí.",
