  ["_Route10CooltrainerF1EndBattleText"] = "\n¡Volví a perder!",
  ["_Route10CooltrainerF2AfterBattleText"] = "¡Estos POKéMON\nson tan robustos!\v¡Debería haber\valguno rosa con\vbonitas flores!",
  ["_Route10CooltrainerF2BattleText"] = "¡Me siento débil\ntras la escalada!",
  ["_Route10CooltrainerF2EndBattleText"] = "¡No\ntengo ganas!",
  ["_Route10Hiker1AfterBattleText"] = "¡Ahah-ah-chús!\n¡Ah-chús!\v(Soplido)...\v(Gimoteo)...",
