  ["_Route11Gate2FOaksAideItemfinderDescriptionText"] = "En el suelo hay\nobjetos que no se\vpueden ver.\fEl BUSCAOBJETOS\ndetectará todo\vobjeto cercano.\f¡Pero no puede\nseñalarlo, así\vque tú tendrás\vque encontrarlo!",
  ["_Route11Gate2FRightBinocularsText"] = "Miraste por los\nprismáticos.\f¡Puedes ir de\nla CIUDAD CELESTE\val PUEBLO\vLAVANDA por el\vTÚNEL ROCA!",
  ["_Route11SuperNerd1AfterBattleText"] = "¡Di a todos\nque ahorren\venergía!",
  ["_Route11SuperNerd1BattleText"] = "¡Cuidado! ¡Estoy\ncolocando unos\vcables!",
  ["_Route11SuperNerd1EndBattleText"] = "¡Muy\neléctrico!",
