  ["_Route11Youngster2BattleText"] = "¡Soy un nuevo\nentrenador! ¡Pero\vcreo que puedo\vganar!",
  ["_Route11Youngster2EndBattleText"] = "¡Mis\nPOKéMON\vperdieron!",
  ["_Route11Youngster3AfterBattleText"] = "Hay un gordo\nPOKéMON que\vbaja de las\vmontañas.\fEs muy fuerte,\npero primero hay\vque atraparlo.",
  ["_Route11Youngster3BattleText"] = "¡Soy el mejor\nde mi clase!",
  ["_Route11Youngster3EndBattleText"] = "\n¡Maldición! ¡Mis\vPOKéMON deben\vser más fuertes!",
  ["_Route11Youngster4AfterBattleText"] = "¡Mejor hallar\nunos más fuertes!",
