  ["_Route11Youngster4EndBattleText"] = "¡Soy\ndemasiado joven!",
  ["_Route12CooltrainerMAfterBattleText"] = "¡Podría haber\ntransformado a\vmis POKéMON con\vuna PIEDRA LUNAR!",
