  ["_Route12Fisher1BattleText"] = "¡Bien! ¡Ha\npicado algo!",
  ["_Route12Fisher1EndBattleText"] = "\n¡Bah! ¡Era muy\vpequeñajo!",
  ["_Route12Fisher2AfterBattleText"] = "¡Con una CAÑA\nmejor podría\vpescar mejores\vPOKéMON!",
