  ["_Route12Fisher3EndBattleText"] = "¡Eso\nfue demasiado!",
  ["_Route12Fisher4AfterBattleText"] = "Está bien.\nPerder ya no\vme importa.",
  ["_Route12Fisher4BattleText"] = "¡Preferiría estar\ntrabajando!",
  ["_Route12Fisher4EndBattleText"] = "No\nes fácil...",
  ["_Route12Fisher5AfterBattleText"] = "¡Es fácil pescar\nMAGIKARP, son\vtan débiles!",
  ["_Route12Fisher5BattleText"] = "¡Nunca se sabe\nlo que podrías\vpescar!",
  ["_Route12Fisher5EndBattleText"] = "\n¡He perdido!",
  ["_Route12Gate1FGuardText"] = "Hay una bonita\nvista arriba.",
  ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "¡{PLAYER} obtuvo\nla MT39!",
  ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "¡La MT39 es un\nataque que se\vllama RAPIDEZ!\fEs muy preciso.\nÚsalo en aquellas\vbatallas que no\vpuedas permitirte\vperder.",
  ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "¡No tienes sitio\npara esto!",
  ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "Las cenizas de\nmis POKéMON están\vguardadas en la\vTORRE POKéMON.\fPuedes quedarte\ncon mi MT. Ya no\vla necesito...",
  ["_Route12Gate2FLeftBinocularsText"] = "Miraste por los\nprismáticos.\f¡Un hombre está\npescando!",
  ["_Route12Gate2FRightBinocularsText"] = "Miraste por los\nprismáticos.\f¡Es la TORRE\nPOKéMON!",
  ["_Route12SignText"] = "RUTA 12: \nLAVANDA al norte",
  ["_Route12SnorlaxCalmedDownText"] = "SNORLAX se calmó.\n¡Y tras bostezar\vregresó a las\vmontañas!",
  ["_Route12SnorlaxText"] = "¡Un POKéMON\ndormido bloquea\vel camino!",
  ["_Route12SnorlaxWokeUpText"] = "¡SNORLAX se\ndespertó!\f¡Se enfadó mucho\ny ataca furioso!",
  ["_Route12SportFishingSignText"] = "ZONA DE PESCA",
  ["_Route12SuperNerdAfterBattleText"] = "El agua conduce\nla electricidad.\v¡Deberías poder\vatrapar a los\vPOKéMON del mar!",
  ["_Route12SuperNerdBattleText"] = "¡Soy un experto\nen electricidad!",
  ["_Route12SuperNerdEndBattleText"] = "\n¡Se acabó!",
  ["_Route12SuperRodHouseFishingGuruDoYouLikeToFishText"] = "¡Soy hermano del\nGURÚ PESCADOR!\f¡Simplemente me\nencanta pescar!\f¿Te gusta pescar?",
  ["_Route12SuperRodHouseFishingGuruFishingWayOfLifeText"] = "¡La pesca es una\nforma de vida!\f¡Del mar a los\nríos, pesca el\vmás grande!",
  ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "¡Oh no!\f¡Tenía un regalo\npara ti, pero no\vtienes sitio!",
  ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "¡Genial! ¡Me\ngusta tu estilo!\f¡Toma esto y\npesca, jovencito!\f¡{PLAYER} obtuvo\n{RAM:wStringBuffer}!",
  ["_Route12SuperRodHouseFishingGuruThatsDisappointingText"] = "Oh... Estoy tan\ndecepcionado...",
  ["_Route12SuperRodHouseFishingGuruTryFishingText"] = "¡Hola,\n{PLAYER}!\f¡Utiliza la SÚPER\nCAÑA en todo tipo\vde aguas! Puedes\vpescar diferentes\vtipos de POKéMON.\f¡Pesca siempre\nque puedas!",
  ["_Route13Beauty1AfterBattleText"] = "¿Cuál es más\nfuerte, un\vPOKéMON femenino\vo masculino?",
  ["_Route13Beauty1BattleText"] = "¡Claro que\njugaré contigo!",
  ["_Route13Beauty1EndBattleText"] = "¡Oh!\n¡Qué bruto eres!",
