  ["_Route13CooltrainerF2BattleText"] = "¡Qué chulas son\ntus MEDALLAS!",
  ["_Route13CooltrainerF2EndBattleText"] = "¡No\nfue suficiente!",
  ["_Route13CooltrainerF3AfterBattleText"] = "¡Tienes que hacer\nluchar a tus\vPOKéMON para\vfortalecerlos!",
  ["_Route13CooltrainerF3BattleText"] = "Mis simpáticos\nPOKéMON desean\vconocerte.",
  ["_Route13CooltrainerF3EndBattleText"] = "\n¡Uauu! ¡Me has\vmachacado!",
