  ["_ViridianForestYoungster4BattleText"] = "¡Eh, espera!\n¿Por qué tienes\vtanta prisa?",
  ["_ViridianForestYoungster4EndBattleText"] = "\n¡Me rindo! ¡Eres\vdemasiado bueno!",
