  ["_ViridianGymCooltrainerM2EndBattleText"] = "\n¡Perdí el\vcontrol!",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "¡Sólo accederás a\nla LIGA POKéMON\vganando a nuestro\vLíDER-GIMNASIO!",
  ["_ViridianGymCooltrainerM3BattleText"] = "¡El GIM. VERDE\nestuvo cerrado\vmucho tiempo,\vpero nuestro\vLÍDER ha vuelto!",
  ["_ViridianGymCooltrainerM3EndBattleText"] = "\n¿Acaso fui\vderrotado?",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "¡Con la MEDALLA-\nTIERRA, todos los\vPOKéMON te\vobedecerán!\f¡Es una prueba de\ntu maestría como\ventrenador de\vPOKéMON!\f¡Con ella podrás\nacceder a la\vLIGA POKéMON!\f¡Es mi regalo por\ndesafiar a la\vLIGA POKéMON!",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "¡Como perdí, ya\nno soy digno de\vdirigir a mis\vsecuaces! ¡Se\vacabó el TEAM\vROCKET!\f¡Dedicaré mi vida\nal estudio de\vlos POKéMON!\f¡Espero que nos\nvolvamos a ver!\v¡Adiós!",
  ["_ViridianGymGiovanniPreBattleText"] = "¡Ajajaja! ¡Ésta\nes mi guarida!\f¡Quería reformar\nal TEAM ROCKET\vdesde aquí!\f¡Pero me volviste\na encontrar!\v¡Estoy furioso!\v¡Esta vez no me\vpienso contener!\f¡Volverás a\nenfrentarte al\vgran GIOVANNI, el\vsúper entrenador!",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "¡Ja!\n¡Fue un duro\vcombate! ¡Y has\vganado! ¡Como\vpremio, toma esta\vMEDALLA-TIERRA!",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "¡{PLAYER} ganó\nla MT27!",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "¡MT27 es FISURA!\n¡Ésta derrotará\va los POKéMON de\vun solo ataque!\fLa inventé cuando\ndirigía este\vGIMNASIO, hace ya\vmucho tiempo...",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "¡No tienes sitio\npara esto!",
  ["_ViridianGymGuidePostBattleText"] = "¿Qué dices? ¿Que\nGIOVANNI era el\vLÍDER del\vGIMNASIO?",
  ["_ViridianGymGuidePreBattleText"] = "¡Hola,\nposible campeón!\f¡Ni yo conozco\nla identidad del\vLÍDER VERDE!\f¡Éste será el más\nduro de todos los\vLÍDERES-GIMNASIO!\f¡Dicen que estos\nentrenadores usan\vlos POKéMON\vdel tipo TIERRA!",
  ["_ViridianGymHiker1AfterBattleText"] = "¡Sigo sin\nmerecérmelo!",
  ["_ViridianGymHiker1BattleText"] = "¡Groaar! ¡Estoy\nempezando a\venfurecerme!",
  ["_ViridianGymHiker1EndBattleText"] = "¡Rargh!",
  ["_ViridianGymHiker2AfterBattleText"] = "Si mis POKéMON\nfueran tan buenos\vkaratekas...",
  ["_ViridianGymHiker2BattleText"] = "¡El karate es lo\nmáximo en artes\vmarciales!",
  ["_ViridianGymHiker2EndBattleText"] = "¡Aachú!",
  ["_ViridianGymHiker3AfterBattleText"] = "¿La LIGA POKéMON?\n¿Tú? ¿Pero quién\vte crees?",
  ["_ViridianGymHiker3BattleText"] = "¡Soy el REY del\nKARATE! ¡Te tengo\ven mis manos!",
  ["_ViridianGymHiker3EndBattleText"] = "¡Yaha!",
